import { describe, it, expect } from "@rstest/core";

import { parseTree } from "@utils/tree";
import { checkConsistency, minimizeConsistency, runConsistencySession } from "@utils/consistency";

/**
 * Regressions found by the consistency checking (minimized by
 * {@link minimizeConsistency}), on designs originally generated by
 * {@link buildRandomDesign}.
 */
function design1(): void {
	parseTree(
		"(1,0,1),(1,2,3),(0,3,1),(0,4,3),(1,5,2),(1,6,1),(6,7,3),(3,8,2),(3,9,3),(7,10,2),(6,11,1),(10,12,1)",
		"(2,5,10,2,0),(4,2,17,0,0),(5,2,5,0,1),(8,5,23,0,2),(9,6,30,2,2),(11,0,10,0,1),(12,13,43,1,2)"
	);
}

function design10(): void {
	parseTree(
		"(2,0,3),(0,1,1),(2,3,2),(3,4,3),(3,5,1),(3,6,3),(2,7,3),(0,8,2),(3,9,3),(7,10,2),(6,11,2),(10,12,3)",
		"(1,5,12,1,2),(4,1,23,0,1),(5,-1,19,1,0),(8,6,33,0,2),(9,1,1,1,2),(11,-4,42,0,1),(12,6,55,1,2)"
	);
}

describe("Consistency", () => {

	it("Yields the same graphics as computing from scratch", () => {
		let report: string | null = null;
		for(let seed = 1; seed <= 20 && !report; seed++) {
			const failure = runConsistencySession(seed, 100, 5);
			if(!failure) continue;
			const ops = minimizeConsistency(failure);
			const repro = ops.map(o => `\t"${o}",`).join("\n");
			report = `seed ${seed}: ${failure.diff}\n${repro}`;
		}
		expect(report).to.be.null;
	});

	it("Clears pattern contours on nodes leaving the node set", () => {
		// Joining node 7 removes node 0 from the node set of stretch 12,101,
		// leaving its pattern contour behind, which shows up again in the river
		// once the root flips and node 0 represents the river (0,1).
		expect(checkConsistency(design1, [
			"length 0=3", "join 10", "addLeaf 101@8->(3,24)", "drag 101->(5,22)",
			"drag 12->(17,11)", "dragEnd", "join 7", "addLeaf 108@12->(20,9)",
			"join 8",
		])).to.be.null;
	});

	it("Updates ids only for the pattern contours of the same repo", () => {
		// Node 6 is in both stretches 9,106 and 107,108. Updating the node set
		// of the former must not touch the pattern contours of the latter, or
		// they are inserted into rivers unrelated to them.
		expect(checkConsistency(design1, [
			"length 0=3", "join 10", "addLeaf 101@8->(3,24)", "length 2=1",
			"join 7", "addLeaf 103@101->(16,28)", "join 101", "drag 9->(5,-13)",
			"dragEnd", "addLeaf 106@6->(-3,-8)", "addLeaf 107@2->(-5,25)",
			"addLeaf 108@12->(20,9)", "join 8", "drag 107->(-5,13)", "dragEnd",
			"addLeaf 109@103->(17,28)", "removeLeaf [4]", "flap 108->(3,5,1,0)",
			"dragEnd", "addLeaf 111@109->(22,-11)",
		])).to.be.null;
	});

	it("Ignores free corners of unrelated stretches in river ridges", () => {
		// The gadget of stretch 10,102 overlaps river (0,2) in this invalid
		// layout, with a free corner at (3,16) on one of the ridges of the
		// river. The river is not in the stretch, so the ridge must not stop
		// there; otherwise it remains split even after the stretch disappears,
		// as nothing else about the river changes.
		expect(checkConsistency(design10, [
			"removeLeaf [12]", "length 10=3", "addLeaf 102@5->(-2,19)",
			"length 5=4", "drag 102->(6,-6)",
		])).to.be.null;
	});
});
